# الصور متحوّلة base64 ومدمجة جوه الكود عشان تفضل شغالة
# جوه streamlit components.html (اللي بيشتغل جوه iframe منعزل
# ومش بيقدر يوصل لملفات مرفوعة بمسار نسبي زي "yasso1.jpeg").
MEMORIES_JSON = """[{"img": "data:image/jpeg;base64,", "text": "Happy Birthday Yasso ❤️"}, {"img": "data:image/jpeg;base64,", "text": "أحلى دني وأجمل صدفة 🌸"}, {"img": "data:image/jpeg;base64,", "text": "سنة حلوة تشبه عيونك ✨"}, {"img": "data:image/jpeg;base64,", "text": "دائماً منورة حياتي يا ياسو 💖"}, {"img": "data:image/jpeg;base64,", "text": "ضحكتك بالدنيا كلها 😍"}, {"img": "data:image/jpeg;base64,", "text": "ربنا يخليكي ليا دايماً 🧿"}, {"img": "data:image/jpeg;base64,", "text": "كل سنة وأنتِ أقرب لي قلبي 💞"}, {"img": "data:image/jpeg;base64,", "text": "يا أجمل ما شافته عيني ✨"}, {"img": "data:image/jpeg;base64,", "text": "سندريلا بتاعتي 👑"}, {"img": "data:image/jpeg;base64,", "text": "معاكِ الحياة أحلى كتير 🥰"}, {"img": "data:image/jpeg;base64,", "text": "ربنا ما يحرمني من وجودك 🤲"}, {"img": "data:image/jpeg;base64,", "text": "يا احلى فتاة في الكون 🌹"}, {"img": "data:image/jpeg;base64,", "text": "بحبك يا ياسو ❤️"}]"""

html_code = """
<!DOCTYPE html>
<html dir="rtl">
<head>
    <meta charset="UTF-8">
    <style>
        html, body {
            background-color: #050510;
            margin: 0;
            padding: 0;
            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;
            overflow: hidden;
            height: 100%;
            width: 100%;
        }
        body {
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
        }

        #countdown-screen {
            font-size: 5em;
            color: #ff3366;
            font-weight: bold;
            text-shadow: 0 0 30px rgba(255,51,102,0.8);
            animation: pulse 1s infinite alternate;
            text-align: center;
        }

        @keyframes pulse {
            0% { transform: scale(1); opacity: 0.8; }
            100% { transform: scale(1.1); opacity: 1; }
        }

        #main-content {
            display: none;
            text-align: center;
            width: 100%;
            height: 100vh;
            position: relative;
            background: radial-gradient(circle, #1a001a 0%, #050510 100%);
            overflow: hidden;
        }

        .card-container {
            position: absolute;
            top: 45%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 300px;
            height: 380px;
            cursor: pointer;
        }

        .card {
            width: 100%;
            height: 100%;
            position: absolute;
            border-radius: 20px;
            box-shadow: 0 10px 30px rgba(255,51,102,0.5);
            border: 4px solid #ff3366;
            background-color: #222;
            background-size: cover;
            background-position: center;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            padding-bottom: 20px;
            transition: transform 0.3s ease;
        }

        .card:active {
            transform: scale(0.95);
        }

        .card-text {
            background: rgba(0, 0, 0, 0.8);
            color: white;
            padding: 8px 18px;
            border-radius: 15px;
            font-size: 16px;
            font-weight: bold;
            text-shadow: 0 0 5px #ff3366;
            border: 1px solid #ff3366;
        }

        .instruction {
            position: absolute;
            bottom: 40px;
            width: 100%;
            text-align: center;
            color: #ff99bb;
            font-size: 18px;
            animation: bounce 1.5s infinite;
        }

        @keyframes bounce {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-8px); }
        }

        .counter {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            color: #ff99bb;
            font-size: 14px;
            letter-spacing: 2px;
        }
    </style>
</head>
<body>

    <div id="countdown-screen">3</div>

    <div id="main-content">
        <div class="counter" id="counterText">1 / 13</div>
        <div class="card-container" onclick="nextCard()">
            <div class="card" id="currentCard">
                <div class="card-text" id="cardText">Happy Birthday Yasso ❤️</div>
            </div>
        </div>
        <div class="instruction">اضغط على الكارت لتشوف الذكريات ✨</div>
    </div>

    <script>
        let count = 3;
        const countdownEl = document.getElementById(\'countdown-screen\');
        const mainContent = document.getElementById(\'main-content\');

        const timer = setInterval(() => {
            count--;
            if (count > 0) {
                countdownEl.innerText = count;
            } else if (count === 0) {
                countdownEl.innerText = "HAPPY BIRTHDAY YASSO ✨";
                countdownEl.style.fontSize = "2.2em";
            } else {
                clearInterval(timer);
                countdownEl.style.display = \'none\';
                mainContent.style.display = \'block\';
            }
        }, 1000);

        // الصور جايه base64 (data URI) مدمجة جوه الصفحة نفسها
        // عشان تشتغل مضمون فى أي مكان من غير ما تعتمد على مسارات ملفات خارجية
        const memories = __MEMORIES_PLACEHOLDER__;

        let currentIndex = 0;
        const currentCard = document.getElementById(\'currentCard\');
        const cardText = document.getElementById(\'cardText\');
        const counterText = document.getElementById(\'counterText\');

        function loadCard(idx) {
            currentCard.style.backgroundImage = `url(\'${memories[idx].img}\')`;
            cardText.innerText = memories[idx].text;
            counterText.innerText = (idx + 1) + " / " + memories.length;
        }

        // تحميل أول صورة افتراضياً
        loadCard(0);

        function nextCard() {
            currentIndex = (currentIndex + 1) % memories.length;
            loadCard(currentIndex);
        }
    </script>
</body>
</html>
"""

html_code = html_code.replace("__MEMORIES_PLACEHOLDER__", MEMORIES_JSON)

components.html(html_code, height=750, scrolling=False)
